#include "runtime_route_model.hpp"
#include "buffered_csv_reader.hpp"
#include "buffered_csv_writer.hpp"
#include <filesystem>
#ifndef RUNTIME_BATCH_SIZE
#define RUNTIME_BATCH_SIZE 32
#endif
#ifndef RUNTIME_COMPONENT_PROFILE
#define RUNTIME_COMPONENT_PROFILE 0
#endif
static std::string_view trimmed(std::string_view s){auto a=s.find_first_not_of(" \r\n\t"),b=s.find_last_not_of(" \r\n\t");return a==s.npos?std::string_view{}:s.substr(a,b-a+1);}
int main(int argc,char**argv){try{
 std::string input,output,feature_path,base_path;for(int i=1;i<argc;++i){std::string a=argv[i];if(i+1==argc)throw std::runtime_error("Missing argument");if(a=="-in")input=argv[++i];else if(a=="-out")output=argv[++i];else if(a=="--feature-out")feature_path=argv[++i];else if(a=="--base-out")base_path=argv[++i];else throw std::runtime_error("Unknown argument");}if(input.empty()||output.empty())throw std::runtime_error("Input and output required");auto folder=std::filesystem::absolute(argv[0]).parent_path();auto canonical=[](const std::string&p){return std::filesystem::weakly_canonical(std::filesystem::absolute(p));};if(canonical(input)==canonical(output)||(!feature_path.empty()&&canonical(feature_path)==canonical(output))||(!base_path.empty()&&canonical(base_path)==canonical(output)))throw std::runtime_error("Output collision");for(const char*asset:{"source-hints.bin","near-curves.bin","far-curves.bin","phi-patterns.bin","correction.bin","estimate"})if(canonical(output)==canonical((folder/asset).string()))throw std::runtime_error("Asset output collision");
 auto start=std::clock();Graph graph;RuntimeRouteModel model(graph,folder.string());FastPinParser parser;parser.enable_scan_coordinates();parser.enable_packed_port_index();double init=double(std::clock()-start)/CLOCKS_PER_SEC;BufferedCsvReader reader(input);BufferedCsvWriter writer(output);std::string_view line;if(!reader.next(line)||trimmed(line)!="From,To")throw std::runtime_error("CSV header");std::ofstream features,bases;if(!feature_path.empty())features.open(feature_path,std::ios::binary);if(!base_path.empty())bases.open(base_path,std::ios::binary);
 struct Pending{std::string_view from,to;PreparedKernelRequest request;};std::array<Pending,RUNTIME_BATCH_SIZE>pending;unsigned used=0;uint64_t rows=0;double prefetch_cpu=0,base_cpu=0,forest_output_cpu=0,selected_prefetch_cpu=0;auto flush=[&](){auto t0=RUNTIME_COMPONENT_PROFILE?std::clock():0;for(unsigned i=0;i<used;++i)model.resolve_operator_cache(pending[i].request);for(unsigned i=0;i<used;++i)model.prefetch(pending[i].request);auto t1=RUNTIME_COMPONENT_PROFILE?std::clock():0;std::array<KernelTrace,RUNTIME_BATCH_SIZE>trace;std::array<int,RUNTIME_BATCH_SIZE>baseline;for(unsigned i=0;i<used;++i)baseline[i]=model.base(pending[i].request,trace[i]);auto tb=RUNTIME_COMPONENT_PROFILE?std::clock():0;for(unsigned i=0;i<used;++i)model.prefetch_selected_codes(pending[i].request,trace[i]);for(unsigned i=0;i<used;++i)model.prefetch_selected_patterns(pending[i].request,trace[i]);std::array<bool,RUNTIME_BATCH_SIZE>needs;for(unsigned i=0;i<used;++i){needs[i]=model.needs_correction(pending[i].request,trace[i],baseline[i]);if(needs[i])model.prefetch_selected_features(pending[i].request,trace[i]);}auto t2=RUNTIME_COMPONENT_PROFILE?std::clock():0;for(unsigned i=0;i<used;++i){auto&r=pending[i];std::array<float,selectedschema::COUNT>x;int value=baseline[i];if(needs[i]||features.is_open()){int corrected=model.correct(r.request,trace[i],baseline[i],features.is_open()?&x:nullptr);if(needs[i])value=corrected;}writer.row(r.from,r.to,value);if(features.is_open())features.write(reinterpret_cast<const char*>(x.data()),sizeof x);if(bases.is_open())bases.write(reinterpret_cast<const char*>(&baseline[i]),4);++rows;}if(RUNTIME_COMPONENT_PROFILE){auto t3=std::clock();prefetch_cpu+=double(t1-t0)/CLOCKS_PER_SEC;base_cpu+=double(tb-t1)/CLOCKS_PER_SEC;selected_prefetch_cpu+=double(t2-tb)/CLOCKS_PER_SEC;forest_output_cpu+=double(t3-t2)/CLOCKS_PER_SEC;}used=0;};reader.set_before_refill([&](){if(used)flush();});
 while(reader.next(line)){line=trimmed(line);if(line.empty())continue;auto c=line.find(',');if(c==line.npos||line.find(',',c+1)!=line.npos)throw std::runtime_error("CSV row");auto from=trimmed(line.substr(0,c)),to=trimmed(line.substr(c+1));auto&r=pending[used++];r.from=from;r.to=to;model.prepare(parser.pin(from),parser.pin(to),r.request);if(used==pending.size())flush();}if(used)flush();writer.finish();if(features.is_open()){features.flush();if(!features)throw std::runtime_error("Feature output");}if(bases.is_open()){bases.flush();if(!bases)throw std::runtime_error("Base output");}model.report_operator_cache();if(RUNTIME_COMPONENT_PROFILE)std::cerr<<"component_prefetch_cpu="<<prefetch_cpu<<" component_base_cpu="<<base_cpu<<" component_selected_prefetch_cpu="<<selected_prefetch_cpu<<" component_forest_output_cpu="<<forest_output_cpu<<'\n';std::cerr<<"rows="<<rows<<" cpu_seconds="<<double(std::clock()-start)/CLOCKS_PER_SEC<<" initialization_seconds="<<init<<" arch_sha256="<<archdata::HASH<<'\n';
}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<'\n';return 1;}}
